<template>
  <div class="gallery-container">
    <!-- Category Selection Bar -->
    <div class="category-bar">
      <button
        v-for="category in categories"
        :key="category.name"
        :class="{ active: selectedCategory === category.name }"
        @click="selectCategory(category.name)"
      >
        {{ category.name }}
      </button>
    </div>

    <!-- Image Grid -->
    <div class="image-grid">
      <div
        v-for="(image, index) in currentCategoryImages"
        :key="index"
        class="image-item"
        @click="openFullscreen(image)"
      >
        <img :src="image.src" :alt="image.alt" />
      </div>
    </div>

    <!-- Fullscreen Image View -->
    <div
      v-if="showFullscreen"
      class="fullscreen-overlay"
      @click.self="closeFullscreen"
    >
      <button class="close-button" @click="closeFullscreen">X</button>
      <button class="nav-button prev" @click="prevImage"><</button>
      <img
        :src="selectedImage.src"
        :alt="selectedImage.alt"
        class="fullscreen-image"
        @click.stop="zoomImage"
      />
      <button class="nav-button next" @click="nextImage">></button>
      <p class="fullscreen-description">{{ selectedImage.description }}</p>
    </div>
  </div>
</template>

<script>
import { ref, onMounted } from "vue";

export default {
  setup() {
    // Sample Image Data (Replace with your actual images)
    const categories = ref([
      {
        name: "Info-Graphics",
        images: [
          {
            src: require("@/assets/images/image1.jpg"),
            alt: "House 1",
            description: "Modern house design",
          },
          {
            src: require("@/assets/images/image2.jpg"),
            alt: "House 2",
            description: "Contemporary house",
          },
          {
            src: require("@/assets/images/image3.jpg"),
            alt: "House 3",
            description: "Luxury house design",
          },
          {
            src: require("@/assets/images/image1.jpg"),
            alt: "House 4",
            description: "Minimalist house design",
          },
          {
            src: require("@/assets/images/image2.jpg"),
            alt: "House 5",
            description: "Spacious house design",
          },
        ],
      },
      {
        name: "Logos",
        images: [
          {
            src: require("@/assets/images/image1.jpg"),
            alt: "Apartment 1",
            description: "Cozy apartment",
          },
          {
            src: require("@/assets/images/image2.jpg"),
            alt: "Apartment 2",
            description: "Modern apartment",
          },
          {
            src: require("@/assets/images/image3.jpg"),
            alt: "Apartment 3",
            description: "Luxury apartment",
          },
        ],
      },
      {
        name: "Branding",
        images: [
          {
            src: require("@/assets/images/image1.jpg"),
            alt: "Building 1",
            description: "Office building",
          },
          {
            src: require("@/assets/images/image2.jpg"),
            alt: "Building 2",
            description: "Commercial building",
          },
        ],
      },
      {
        name: "Labels",
        images: [
          {
            src: require("@/assets/images/image2.jpg"),
            alt: "Interior 1",
            description: "Modern interior design",
          },
          {
            src: require("@/assets/images/image3.jpg"),
            alt: "Interior 2",
            description: "Cozy interior",
          },
        ],
      },
    ]);

    const selectedCategory = ref(categories.value[0].name); // Initial category
    const selectedImage = ref(null);
    const showFullscreen = ref(false);

    const currentCategoryImages = ref(categories.value[0].images);

    const selectCategory = (categoryName) => {
      selectedCategory.value = categoryName;
      currentCategoryImages.value = categories.value.find(
        (cat) => cat.name === categoryName
      ).images;
    };

    const openFullscreen = (image) => {
      selectedImage.value = image;
      showFullscreen.value = true;
    };

    const closeFullscreen = () => {
      showFullscreen.value = false;
    };

    const nextImage = () => {
      const currentIndex = currentCategoryImages.value.indexOf(
        selectedImage.value
      );
      const nextIndex = (currentIndex + 1) % currentCategoryImages.value.length;
      selectedImage.value = currentCategoryImages.value[nextIndex];
    };

    const prevImage = () => {
      const currentIndex = currentCategoryImages.value.indexOf(
        selectedImage.value
      );
      const prevIndex =
        (currentIndex - 1 + currentCategoryImages.value.length) %
        currentCategoryImages.value.length;
      selectedImage.value = currentCategoryImages.value[prevIndex];
    };

    const zoomImage = () => {};

    onMounted(() => {
      document.addEventListener("keydown", handleArrowKeys);
    });

    const handleArrowKeys = (event) => {
      if (showFullscreen.value) {
        if (event.key === "ArrowRight") {
          nextImage();
        } else if (event.key === "ArrowLeft") {
          prevImage();
        }
      }
    };

    return {
      categories,
      selectedCategory,
      selectedImage,
      showFullscreen,
      currentCategoryImages,
      selectCategory,
      openFullscreen,
      closeFullscreen,
      nextImage,
      prevImage,
      zoomImage,
    };
  },
};
</script>

<style scoped>
:root {
  --gallery-image-height: 200px;
}

.gallery-container {
  padding-top: 3rem;
  height: 100%; /* Changed from 100vh */
  box-sizing: border-box;
  background-color: #111;
}

/* Category Bar */
.category-bar {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}

.category-bar button {
  background-color: #555;
  border: none;
  padding: 10px 20px;
  margin: 0 5px;
  cursor: pointer;
  border-radius: 5px;
  transition: background-color 0.3s ease;
}

.category-bar button.active {
  background-color: red;
  color: white;
}
.category-bar button:hover {
  background-color: #777;
  transform: scale(1.05);
}

/* Image Grid */
.image-grid {
  display: grid;
  grid-template-columns: repeat(
    auto-fit,
    minmax(300px, 1fr)
  ); /* Enforce 3+ images per column */
  gap: 20px;
  height: calc(
    100% - 60px
  ); /* subtracts the top 60px from the bottom part of the display so that its all within view.*/
  overflow: auto;
}

.image-item {
  cursor: pointer;
  border-radius: 5px;
  overflow: hidden;
  transition: transform 0.3s ease;
}

.image-item:hover {
  transform: scale(1.05);
}

.image-item img {
  width: 100%;
  height: var(--gallery-image-height);
  object-fit: cover;
  display: block;
}

/* Fullscreen Overlay */
.fullscreen-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.9);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
}

.close-button {
  position: absolute;
  top: 20px;
  right: 20px;
  background-color: transparent;
  border: none;
  color: white;
  font-size: 2em;
  cursor: pointer;
  transition: color 0.3s ease;
}

.close-button:hover {
  color: red;
}

.nav-button {
  background-color: transparent;
  border: 2px solid red;
  border-radius: 50%;
  color: white;
  font-size: 2em;
  height: 80px;
  width: 80px;
  cursor: pointer;
  transition: background-color 0.3s ease;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
}
.nav-button:hover {
  border: 2px solid #555;
  color: red;
  transition: all ease-in-out 0.5s;
}

.nav-button.prev {
  left: 50px;
}

.nav-button.next {
  right: 50px;
}

.fullscreen-image {
  max-width: 80%;
  max-height: 70vh;
  border-radius: 5px;
  cursor: pointer;
}

.fullscreen-description {
  color: white;
  font-size: 1.2em;
  margin-left: 4rem;
  text-align: center;
}

/* Responsive Design */
@media (max-width: 768px) {
  .image-grid {
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  }

  .fullscreen-image {
    max-width: 95%;
    max-height: 60vh;
  }
}
</style>
